"""Entry point: python3 server.py <port>"""
import sys
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

from app import handlers, middleware, negotiate
from app.legacy_handler import reject_bad_method
from app.router import Router
from app.store import Store

STORE = Store("data/animals.json")
ROUTER = Router()
ROUTER.add("GET", "/lookup", handlers.lookup)

PIPELINE = middleware.chain(
    middleware.with_content_length,
    middleware.with_error_envelope,
)(lambda ctx: dispatch(ctx))


def dispatch(ctx):
    status, handler = ROUTER.resolve("GET", ctx["path"])
    if status != "ok":
        raise middleware.AppError(404, {"error": "no_route"})
    return handler(ctx)


class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass

    def serve(self):
        bad = reject_bad_method(self.command)
        if bad:
            self.reply(*bad)
            return
        path, params = ROUTER.split(self.path)
        accept = self.headers.get("Accept")
        ctx = {"method": self.command, "path": path, "params": params,
               "accept": accept, "kind": negotiate.choose(accept), "store": STORE}
        self.reply(*PIPELINE(ctx))

    def reply(self, status, headers, body):
        self.send_response(status)
        for k, v in (headers or {}).items():
            self.send_header(k, v)
        self.end_headers()
        if body:
            self.wfile.write(body.encode() if isinstance(body, str) else body)

    def do_GET(self):
        self.serve()

    def do_HEAD(self):
        self.serve()

    def do_POST(self):
        self.serve()


if __name__ == "__main__":
    ThreadingHTTPServer(("127.0.0.1", int(sys.argv[1])), H).serve_forever()

