"""The lookup table. Loaded once at startup."""
import json


class Store:
    def __init__(self, path):
        with open(path, encoding="utf-8") as fh:
            raw = json.load(fh)
        self._by_name = {}
        for name, color in raw.items():
            self._by_name[name.lower()] = color

    def get(self, name):
        return self._by_name.get(name.lower())

    def names(self):
        return sorted(self._by_name)

