"""Content negotiation and body rendering."""
import json

JSON_TYPES = ("application/json", "*/*")


def choose(accept):
    if accept is None or accept in JSON_TYPES:
        return "json"
    if accept == "text/plain":
        return "text"
    return None


def render(payload, kind):
    if kind == "text":
        if isinstance(payload, dict) and "name" in payload and "color" in payload:
            text = "%s: %s\n" % (payload["name"], payload["color"])
        else:
            text = json.dumps(payload, ensure_ascii=False, sort_keys=True) + "\n"
        return "text/plain; charset=utf-8", text
    body = json.dumps(payload, ensure_ascii=False, sort_keys=True)
    return "application/json", body

