"""Route handlers."""
from .middleware import AppError
from . import negotiate


def lookup(ctx):
    name = ctx["params"].get("name")
    color = ctx["store"].get(name or "")
    if color is None:
        raise AppError(404, {"error": "not_found", "name": name})
    if not name:
        raise AppError(400, {"error": "missing_name"})
    return 200, {}, {"name": name, "color": color}

