"""Layers. A handler is f(ctx) -> (status, headers, payload).
A layer is f(next_handler) -> handler."""
from . import negotiate


class AppError(Exception):
    def __init__(self, status, payload):
        Exception.__init__(self, status)
        self.status = status
        self.payload = payload


def chain(*layers):
    def build(inner):
        handler = inner
        for layer in layers:
            handler = layer(handler)
        return handler
    return build


def with_error_envelope(nxt):
    def handler(ctx):
        try:
            return nxt(ctx)
        except AppError as exc:
            return exc.status, {}, exc.payload
        except Exception:
            return 500, {}, {"error": "internal"}
    return handler


def with_content_length(nxt):
    def handler(ctx):
        status, headers, payload = nxt(ctx)
        if payload is None:
            return status, headers, None
        ctype, body = negotiate.render(payload, ctx["kind"])
        headers = dict(headers)
        headers["Content-Type"] = ctype
        headers["Content-Length"] = str(len(body))
        return status, headers, body
    return handler

